import {WORLD_WIDTH,WORLD_HEIGHT} from './evolution.js';
import {localNeighbours,moveLocally,localDistance} from './navigation.js';
import {ACTIONS} from './action-catalog.js';
import {v,p,a,table,details} from './guide-markup.js';

// Учебный маршрут вычисляется теми же функциями, что и навигация жителя.
export function guideNavigationExample(){const brain={position:{q:0,r:0},facing:0};return [0,1,0].map(action=>{moveLocally(brain,action);return {action,position:{...brain.position},facing:brain.facing};});}
const example=guideNavigationExample(),initial={position:{q:0,r:0},facing:0};
export const GUIDE_GEOGRAPHY_TEXT={
 'guide-geography-body':p(`Карта наблюдателя охватывает всё поле: ${v(WORLD_WIDTH)} столбцов и ${v(WORLD_HEIGHT)} строк. Она позволяет выбрать жителя, увидеть пищу и рельеф. Мозг получает локальное наблюдение, а сведения о ранее посещённых местах сохраняет в ${a('memory','личной памяти')}.`)
 +p('У каждого жителя своя система координат. При рождении его личное положение — начало отсчёта. После успешного перехода он учитывает смещение и поворачивает взгляд по направлению движения. Поэтому «вперёд» относится к текущему взгляду, а не к правому краю карты наблюдателя.')
 +table('Пример: вперёд, назад, снова вперёд',['Успешный переход','Личное положение (q; r)','Направление взгляда'],example.map((s,i)=>[`${i+1}. ${ACTIONS[s.action]}`,v(s.position.q)+'; '+v(s.position.r),v(s.facing)]))
 +p('Номер взгляда обозначает направление личной сетки. Второй переход возвращает в место рождения, но разворачивает взгляд. Третий «вперёд» ведёт уже в противоположную сторону. При прерванном переходе ни положение, ни направление взгляда не меняются.')
 +details('Координаты, границы и доступные сведения',
 p('Гекс имеет шесть соседей. Мировая сетка хранит столбец x и строку y; личная навигация использует осевые q и r. Для перевода между ними физика учитывает отдельный поворот личной системы. Этот поворот и глобальные x/y не входят в запрос мозга.')
 +table('Соседи при начальном взгляде',['Команда','Смещение q','Смещение r'],localNeighbours(initial).map((s,i)=>[ACTIONS[i],v(s.q),v(s.r)]))
 +p(`Расстояние между соседними гексами равно ${v(localDistance(initial.position,localNeighbours(initial)[0]))}. Личный учёт успешных шагов точный, в том числе при выключенной памяти. Память влияет на сохранение наблюдений и опыта, а не на выполнение геометрического преобразования.`)
 +p('Поле ограничено: за краем нет клетки, перехода на противоположный край нет. Вода блокирует движение; брод — сухой переход через воду. Другой житель на гексе не запрещает входить туда. Если обзор упирается в край карты, внеполевые клетки в него не добавляются.')
 +p('В видимой клетке сообщаются текущее количество пищи, признак источника, рельеф, число других жителей и их видимая деятельность. Собственная деятельность исключается из счётчиков окружающих. Расписание следующего появления пищи и состояние чужих мозгов в это наблюдение не входят.')
 +p('Профиль «Реки и озёра» создаёт водные преграды и сухие районы. Равномерный старт распределяет основателей по суше, не выбирая места по наличию еды. Seed карты и seed пищи отвечают за разные части окружения. Смена вида отображения наблюдателя не расширяет обзор жителя.'))
 +p(`Связанные темы: ${a('actions','процессы движения')}, ${a('food','источники пищи')}, ${a('environment','изменение среды')}, ${a('brain','оценка доступных действий')}.`),
};
